"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[7636],{28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>o});var a=n(96540);const s={},r=a.createContext(s);function i(e){const t=a.useContext(r);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(r.Provider,{value:t},e.children)}},30540:e=>{e.exports=JSON.parse('{"permalink":"/blog/p1-broken-at-seams","source":"@site/blog/2026-08-31-whyp1-broken-at-seams.md","title":"The Pipeline Compiles, the Demo Works, and the Seams Are Quietly Broken","description":"Part 1 of 4: How a data engineering harness eliminates the AI coding agent errors that survive review.","date":"2026-08-31T00:00:00.000Z","tags":[{"inline":true,"label":"agentic","permalink":"/blog/tags/agentic"},{"inline":true,"label":"data-engineering","permalink":"/blog/tags/data-engineering"}],"readingTime":7.72,"hasTruncateMarker":true,"authors":[{"name":"Matthias Broecheler","title":"CEO of DataSQRL","url":"https://github.com/mbroecheler","page":{"permalink":"/blog/authors/matthias"},"socials":{"linkedin":"https://www.linkedin.com/in/matthiasbroecheler/","github":"https://github.com/mbroecheler","newsletter":"https://www.matthiasb.com"},"imageURL":"/img/headshots/matthias1.png","key":"matthias"}],"frontMatter":{"slug":"p1-broken-at-seams","title":"The Pipeline Compiles, the Demo Works, and the Seams Are Quietly Broken","authors":["matthias"],"tags":["agentic","data-engineering"]},"unlisted":false,"nextItem":{"title":"AI in Data Engineering: Building Reliable Data Systems at Scale","permalink":"/blog/ai-data-engineering"}}')},92154:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>o,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>h});var a=n(30540),s=n(74848),r=n(28453);const i={slug:"p1-broken-at-seams",title:"The Pipeline Compiles, the Demo Works, and the Seams Are Quietly Broken",authors:["matthias"],tags:["agentic","data-engineering"]},o="The Pipeline Compiles, the Demo Works, and the Seams Are Quietly Broken",d={authorsImageUrls:[void 0]},h=[{value:"Introduction",id:"introduction",level:2},{value:"1. The same column, typed three different ways",id:"1-the-same-column-typed-three-different-ways",level:2},{value:"2. Query dialects that look the same and mean different things",id:"2-query-dialects-that-look-the-same-and-mean-different-things",level:2},{value:"3. A field added in one place but not everywhere",id:"3-a-field-added-in-one-place-but-not-everywhere",level:2},{value:"4. Connector configuration where two systems meet",id:"4-connector-configuration-where-two-systems-meet",level:2},{value:"5. An API contract the data model cannot honor",id:"5-an-api-contract-the-data-model-cannot-honor",level:2},{value:"6. Internal columns leaking into the public interface",id:"6-internal-columns-leaking-into-the-public-interface",level:2},{value:"7. The same operation exposed three ways, three different shapes",id:"7-the-same-operation-exposed-three-ways-three-different-shapes",level:2},{value:"8. Identifier casing, quoting, and reserved words",id:"8-identifier-casing-quoting-and-reserved-words",level:2},{value:"Summary",id:"summary",level:2}];function l(e){const t={a:"a",code:"code",em:"em",h2:"h2",p:"p",...(0,r.R)(),...e.components},{Head:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Head",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n,{children:[(0,s.jsx)("meta",{property:"og:image",content:"/img/blog/harness_p1_broken_seams.jpeg"}),(0,s.jsx)("meta",{name:"twitter:image",content:"/img/blog/harness_p1_broken_seams.jpeg"})]}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Part 1 of 4: How a data engineering harness eliminates the AI coding agent errors that survive review."})}),"\n",(0,s.jsx)(t.h2,{id:"introduction",children:"Introduction"}),"\n",(0,s.jsx)(t.p,{children:'"Why do I need that? Isn\'t Claude Code good enough?"'}),"\n",(0,s.jsxs)(t.p,{children:["We get that question a lot. We are building an ",(0,s.jsx)(t.a,{href:"https://docs.datasqrl.com",children:"open-source data engineering harness"}),", the tooling and guardrails that a coding agent uses to build data pipelines. Claude Code, Codex, and OpenCode already write plausible data pipeline code. So what is the harness for?"]}),"\n",(0,s.jsx)("img",{src:"/img/blog/harness_p1_broken_seams.jpeg",alt:"A data pipeline spanning multiple systems with broken seams at the boundaries between them.",width:"50%"}),"\n",(0,s.jsx)(t.p,{children:"This series answers that. It looks at where general-purpose coding harnesses fail on data engineering work, and why those failures survive code review."}),"\n",(0,s.jsx)(t.p,{children:"Part 1 is about the seams. A pipeline spans multiple data systems, and the same fact (a type, a name, an encoding) has to be restated in each one. Restating facts consistently across systems is strict rule-following. The thing doing the restating is a probabilistic model. It gets most of them right. The ones it gets wrong compile cleanly, pass the demo, and surface in production as overflowed numbers and fields that were never there."}),"\n",(0,s.jsx)(t.p,{children:"A transpiler removes that entire class of error. It derives every boundary asset from one logical model, so the systems cannot disagree. The agent also writes less code, which means fewer tokens and fewer duplicated schema definitions cluttering its context."}),"\n",(0,s.jsx)(t.h2,{id:"1-the-same-column-typed-three-different-ways",children:"1. The same column, typed three different ways"}),"\n",(0,s.jsx)(t.p,{children:"A column in a pipeline exists at least three times. Once in the stream processor, once in the database, once in the API schema. Every system has its own type system, and an agent hand-maps between them one file at a time. A 64-bit integer becomes a 32-bit one at the API. A timestamp with a time zone becomes a bare local timestamp. A fixed-precision decimal lands as a floating point number. Nothing errors. The numbers are just wrong at the edges."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," an agent maps a transaction amount, stored as a 64-bit count of cents, to a 32-bit API type. Every transaction above roughly $21M wraps to a negative number. Every test built on small sample values passes."]}),"\n",(0,s.jsx)(t.p,{children:"A transpiler infers the type once from the logical model and generates the matching type for each system, so the three representations cannot drift apart."}),"\n",(0,s.jsx)(t.h2,{id:"2-query-dialects-that-look-the-same-and-mean-different-things",children:"2. Query dialects that look the same and mean different things"}),"\n",(0,s.jsx)(t.p,{children:"Every engine speaks its own dialect. They share a vocabulary and disagree in the details: function names, null handling, division, casts, date arithmetic. An agent writes a transformation in one dialect and a serving query in another. Both run, neither complains, but they compute different answers."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"}),' an integer division floors in the database and returns a fraction in the stream engine. A "share of total" computed in the stream layer and recomputed in a database view disagree for the same row, and nothing in either system flags it.']}),"\n",(0,s.jsx)(t.p,{children:"A transpiler generates each engine's dialect from one logical plan. A single declared computation is translated consistently instead of agent-written twice."}),"\n",(0,s.jsx)(t.h2,{id:"3-a-field-added-in-one-place-but-not-everywhere",children:"3. A field added in one place but not everywhere"}),"\n",(0,s.jsx)(t.p,{children:"Adding one output column is a multi-system edit. The transformation, the connector that moves the data, the database table definition, the API type, and every endpoint that exposes it all have to gain the field together. An agent updates two or three of them and forgets the rest. The column either never reaches the database or arrives and stays invisible to every consumer."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," you ask for a merchant category on an enriched transaction stream. The agent updates the transformation and the database table but not the API type. The field does not exist for any consumer, and there is no error to point at."]}),"\n",(0,s.jsx)(t.p,{children:"With a transpiler you add the column once. Every downstream asset is regenerated from that one definition."}),"\n",(0,s.jsx)(t.h2,{id:"4-connector-configuration-where-two-systems-meet",children:"4. Connector configuration where two systems meet"}),"\n",(0,s.jsx)(t.p,{children:"Wherever two systems meet, a connection has to be configured: names, formats, key fields, write mode. This is hand-written glue, and an agent gets it wrong in ways that never fail loudly. A key field that does not match the table's key. An append-only write for something that is logically an update. A missing time attribute."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," the agent configures the write from the stream layer into the database but never aligns the update key. Concurrent updates race, and the stored row flickers between values."]}),"\n",(0,s.jsx)(t.p,{children:"A transpiler treats every cut between systems as a generated connection. Both sides of every boundary derive from the same source of truth."}),"\n",(0,s.jsx)(t.h2,{id:"5-an-api-contract-the-data-model-cannot-honor",children:"5. An API contract the data model cannot honor"}),"\n",(0,s.jsx)(t.p,{children:"When the API schema is hand-written separately from the queries behind it, the contract drifts away from the data. A field marked as always present that can return nothing. A list marked non-empty that can be empty. An argument whose type does not match the query parameter. The API now advertises guarantees the pipeline cannot keep, and consumers get errors where they were promised values."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," the agent declares a customer's order summary as always non-empty. A customer with zero orders violates the contract and fails the whole query."]}),"\n",(0,s.jsx)(t.p,{children:"A transpiler builds the API schema from the data model. When you supply your own schema, it raises a compile error wherever schema and model disagree, rather than letting the mismatch reach consumers."}),"\n",(0,s.jsx)(t.h2,{id:"6-internal-columns-leaking-into-the-public-interface",children:"6. Internal columns leaking into the public interface"}),"\n",(0,s.jsx)(t.p,{children:"Tables carry columns the system fills in itself: generated ids, ingest timestamps, computed values. An interface that accepts writes must ask clients for the columns they actually supply and nothing else. An agent hand-writing that interface routinely includes the internal ones, so valid writes are rejected, or omits a real one, so writes arrive incomplete."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," the write interface for an event asks for the generated id and the ingest timestamp. Every well-formed client insert is rejected for sending fields the server computes on its own."]}),"\n",(0,s.jsx)(t.p,{children:"A transpiler derives the input contract from the table definition and excludes system-populated columns, so the interface matches what a client is meant to send."}),"\n",(0,s.jsx)(t.h2,{id:"7-the-same-operation-exposed-three-ways-three-different-shapes",children:"7. The same operation exposed three ways, three different shapes"}),"\n",(0,s.jsx)(t.p,{children:"Operations are usually published over more than one protocol. An agent hand-coding each one produces views that disagree. An operation present on one protocol and missing on another. A route using the wrong method for its payload. A path whose arguments do not match the query signature. Consumers on one protocol get a broken endpoint, or none at all."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," a query that takes a filter is exposed as a request that carries the filter in URL parameters. The filter is silently truncated, and every call returns the unfiltered result set."]}),"\n",(0,s.jsx)(t.p,{children:"A transpiler generates every protocol from one authoritative API model, so names, paths, and signatures stay aligned across all of them."}),"\n",(0,s.jsx)(t.h2,{id:"8-identifier-casing-quoting-and-reserved-words",children:"8. Identifier casing, quoting, and reserved words"}),"\n",(0,s.jsx)(t.p,{children:"Systems disagree about case sensitivity, quoting, and which words are reserved. An agent carrying a name across them by hand introduces mismatches that break the mapping from API field to stored column. A mixed-case name folded to lowercase by one system no longer matches the code looking for it. A name that is a reserved word parses on one engine and fails on the next."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.em,{children:"Example:"})," a column named ",(0,s.jsx)(t.code,{children:"order"}),' compiles in the stream layer and produces invalid table definitions in the database. The agent "fixes" it by quoting the name in one place and leaving it unquoted in another, and the API field resolves to nothing.']}),"\n",(0,s.jsx)(t.p,{children:"A transpiler applies one identifier mapping across every generated asset, so a logical name resolves to the right form on every system."}),"\n",(0,s.jsx)(t.h2,{id:"summary",children:"Summary"}),"\n",(0,s.jsx)(t.p,{children:"We could keep going down our list of seam-breaking errors we have seen in agentic implementations, but you get the idea: Don't generate probabilistically what can be derived deterministically from a shared ground truth."}),"\n",(0,s.jsx)(t.p,{children:"That's what the transpiler in the data engineering harness does. It takes one verified logical model as the ground truth and generates every boundary asset from it: the stream transformations, the database schema and queries, the connector configuration at each cut, the API schema, and every protocol endpoint. A type is inferred once and projected into each system. A field added once propagates to every asset. A name maps the same way everywhere. Both ends of a connection come from the same definition."}),"\n",(0,s.jsx)(t.p,{children:'Because a compiler does that mapping instead of a language model, the entire category of "the systems disagree at the seam" does not need review to catch. It cannot be expressed. The agent decides what the pipeline computes. The transpiler guarantees the boundaries agree.'}),"\n",(0,s.jsx)(t.p,{children:"This has the additional benefit that there is a lot less code for the agent to generate at the seams. That means faster implementation, fewer tokens, less context pollution, and less technical debt."}),"\n",(0,s.jsxs)(t.p,{children:["Want to learn more about what exactly gets generated? The transpiler is part of the open source data engineering harness, so you can read exactly what gets generated: ",(0,s.jsx)(t.a,{href:"https://github.com/DataSQRL/sqrl",children:"DataSQRL on GitHub"}),"."]})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}}}]);